package com.basiclab.iot.transform.runtime.service; import com.basiclab.iot.transform.core.domain.OutboxRecord; import com.basiclab.iot.transform.runtime.dal.TransformRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class OutboxService { private final TransformRepository repository; public OutboxService(TransformRepository repository){this.repository=repository;} public Collection<OutboxRecord> list(){return repository.listOutbox();} public OutboxRecord get(String id){return repository.outbox(id);} }